# ==========================================================
# SEQUENCE DATA

## Load pipeline outputs
data.tax <- tax_table(as.matrix(read.table("taxonomy.vsearch", header = TRUE, row.names = 1, fill = TRUE, sep = ",")))
data.otu <- otu_table(read.table("asv_table.merge.txt", header = TRUE, row.names = 1, check.names = FALSE), taxa_are_rows = TRUE)

## Load phylogeny if generated by the pipeline
if (pipeline_phylogeny == 1) {
  data.tre <- read.tree("asvs.tre")
}

# ==========================================================
# SAMPLE METADATA

## Load QC metadata
# Technical/QC metadata generated automatically by the pipeline.
qc.map <- read_sample_metadata_table("samples_metadata.csv", sep = ",")


