# BUILD PHYLOSEQ OBJECT

## Construct phyloseq object
if (pipeline_phylogeny == 1) {
  data.ps <- merge_phyloseq(data.otu, data.tax, data.map, data.tre)
} else {
  data.ps <- merge_phyloseq(data.otu, data.tax, data.map)
}

